-- =====================================================================
-- 「邯道 · 串城街」智慧文旅  ·  数据库初始化脚本
-- 用法：Supabase Dashboard → SQL Editor → New query → 全选粘贴 → Run
-- 可重复执行（幂等）：建表用 if not exists，种子数据用 upsert
-- =====================================================================

-- ---------------------------------------------------------------------
-- 1. 内容层：路线 / 点位 / 笔记 / 商品 / 专题等，统一存 hd_content
--    每个实体一行，data 为完整业务字段（与前端数据结构一一对应）
-- ---------------------------------------------------------------------
create table if not exists public.hd_content (
  kind        text        not null,
  id          text        not null,
  ord         int         not null default 0,
  data        jsonb       not null,
  updated_at  timestamptz not null default now(),
  primary key (kind, id)
);
create index if not exists hd_content_kind_ord_idx on public.hd_content (kind, ord);

-- ---------------------------------------------------------------------
-- 2. 用户资产层：按匿名 uid 隔离（前端 localStorage 生成）
-- ---------------------------------------------------------------------
create table if not exists public.hd_profiles (
  uid        text        primary key,
  points     int         not null default 320,
  created_at timestamptz not null default now(),
  last_seen  timestamptz not null default now()
);

create table if not exists public.hd_favorites (
  uid        text        not null,
  kind       text        not null check (kind in ('note','route','good')),
  target_id  text        not null,
  created_at timestamptz not null default now(),
  primary key (uid, kind, target_id)
);
create index if not exists hd_favorites_uid_idx on public.hd_favorites (uid);

create table if not exists public.hd_trips (
  uid        text        not null,
  route_id   text        not null,
  created_at timestamptz not null default now(),
  primary key (uid, route_id)
);

create table if not exists public.hd_visits (
  uid        text        not null,
  poi_id     text        not null,
  created_at timestamptz not null default now(),
  primary key (uid, poi_id)
);

create table if not exists public.hd_orders (
  no         text        primary key,
  uid        text        not null,
  items      jsonb       not null default '[]'::jsonb,
  qty        int         not null default 1,
  amount     numeric(10,2) not null default 0,
  st         text        not null default 'sent' check (st in ('unpaid','sent','used','done')),
  time       text        not null default '',
  created_at timestamptz not null default now()
);
create index if not exists hd_orders_uid_idx on public.hd_orders (uid, created_at desc);

create table if not exists public.hd_events (
  id         bigserial   primary key,
  uid        text,
  page       text,
  evt        text,
  extra      text,
  ts         timestamptz not null default now()
);
create index if not exists hd_events_ts_idx on public.hd_events (ts desc);

-- ---------------------------------------------------------------------
-- 3. 权限：开启 RLS 且不建任何策略
--    效果：anon / authenticated 一律拒绝，只有服务端 service_role 可读写
--    （本项目所有读写都走 Next.js API Routes，浏览器不直连数据库）
-- ---------------------------------------------------------------------
alter table public.hd_content   enable row level security;
alter table public.hd_profiles  enable row level security;
alter table public.hd_favorites enable row level security;
alter table public.hd_trips     enable row level security;
alter table public.hd_visits    enable row level security;
alter table public.hd_orders    enable row level security;
alter table public.hd_events    enable row level security;

-- ---------------------------------------------------------------------
-- 4. 种子数据：5 条路线 / 17 个点位 / 7 篇笔记 / 11 个商品 ...
-- ---------------------------------------------------------------------
