  ('routes','r1',0,'{"id":"r1","t":"串城街主轴 · 三千年一街","lb":"CITYWALK","ci":0,"sub":"学步桥 → 回车巷 → 秦皇出生地 → 荀子文化园 → 武灵丛台","intro":"从一座因成语得名的明代石桥起步，走进不到 3 米宽的回车巷，再沿串城街北上，最后登上赵武灵王的点将台。这一天，你会看到邯郸如何把三千年折叠进一条 500 多米的街。","days":"1 天","km":"3.4 km","spots":5,"walk":"约 4600 步","heat":"3.1 万人走过","score":4.9,"tags":["历史建筑","城市漫步","成语典故"],"best":"全年 · 春秋最佳，上午 9 点前街上人少","pois":["p1","p2","p3","p4","p5"],"tip":"丛台登台需另购票，台阶陡且窄；回车巷很窄，双向会人需侧身。"}'::jsonb),
  ('routes','r2',1,'{"id":"r2","t":"老城烟火 · 早汤到夜市","lb":"FOOD","ci":6,"sub":"一篓油水饺 → 串城街夜市 → 丛台广场","intro":"一条用胃来丈量的路线。清晨在老字号喝一碗驴肉汤，入夜钻进串城街的夜食摊子，最后在丛台广场坐到路灯亮起。","days":"1 天","km":"2.2 km","spots":3,"walk":"约 3000 步","heat":"1.8 万人走过","score":4.8,"tags":["邯郸美食","市井烟火","夜游"],"best":"全年 · 18:30 后夜市最热闹","pois":["p6","p7","p8"],"tip":"夜市高峰在 18:30-21:00，建议错峰；焖子要趁热吃。"}'::jsonb),
  ('routes','r3',2,'{"id":"r3","t":"赵都溯源 · 都城与王城","lb":"HISTORY","ci":1,"sub":"邯郸市博物馆 → 赵王城遗址 → 赵苑公园","intro":"从八千年前的一粒粟，走到两千多年前那座\"品\"字形的都城。赵国的城市怎么规划、王的苑囿长什么样，这条线上都有实物可看。","days":"1 天","km":"8.6 km","spots":3,"walk":"约 11000 步","heat":"9200 人走过","score":4.8,"tags":["历史","博物馆","遗址"],"best":"全年 · 周一博物馆闭馆，注意避开","pois":["p9","p10","p11"],"tip":"邯郸市博物馆周一闭馆；赵王城遗址以露天展示为主，夏季注意防晒。"}'::jsonb),
  ('routes','r4',3,'{"id":"r4","t":"广府水城 · 城墙与太极","lb":"WATERTOWN","ci":8,"sub":"广府古城墙 → 弘济桥 → 杨露禅故居","intro":"北方少见的水城。明代砖城墙外是护城河与永年洼湿地，城外还有一座与赵州桥同源的隋代石拱桥，以及两大太极拳流派的共同发源地。","days":"1 天","km":"5.8 km","spots":3,"walk":"约 7300 步","heat":"7600 人走过","score":4.8,"tags":["古城","古桥","太极拳"],"best":"春秋 · 夏季洼地蚊虫较多","pois":["p12","p13","p14"],"tip":"点位间约 3-8 km，建议自驾或打车衔接；城墙可租自行车环行。"}'::jsonb),
  ('routes','r5',4,'{"id":"r5","t":"太行寻艺 · 石窟与窑火","lb":"HERITAGE","ci":2,"sub":"响堂山石窟 → 磁州窑遗址 → 娲皇宫","intro":"从北齐的造像，到宋代的窑火，再到挂在崖壁上的楼阁。邯郸西部的太行山麓，藏着北方民间工艺与宗教建筑最密集的一条线索。","days":"1-2 天","km":"42 km","spots":3,"walk":"约 8600 步","heat":"5400 人走过","score":4.9,"tags":["石窟","非遗","山地建筑"],"best":"春秋 · 建议自驾，行程分两天更从容","pois":["p15","p16","p17"],"tip":"三个点位分属不同区县，距离较远，建议自驾或包车；窟内禁止闪光灯。"}'::jsonb),
  ('pois','p1',0,'{"id":"p1","n":"学步桥 · 明代石拱桥","r":"r1","ord":1,"ci":3,"lb":"邯郸学步","cat":"历史建筑","stay":"30 分钟","score":4.7,"rev":9680,"addr":"邯郸市丛台区陵西北大街 · 沁河之上","open":"全天开放","desc":"横跨沁河的明代石拱桥，因\"邯郸学步\"的典故而改名。桥为多孔石拱，两侧设栏板与望柱，青石砌筑、拱券采用纵联式砌法，是研究明代北方石拱桥结构做法难得的实物——桥窄、拱薄、用料省，做法直接服务于当时的通行量。","view":["石拱券","成语浮雕栏板","望柱石狮","沁河水面"],"audio":{"len":"02:36","txt":"语音讲解 · 一座桥和一个成语"},"tips":"桥面仍在通行且较窄，早晚高峰注意来车；看拱券砌法要到桥下河滩侧。"}'::jsonb),
  ('pois','p2',1,'{"id":"p2","n":"回车巷 · 将相和故地","r":"r1","ord":2,"ci":4,"lb":"负荆请罪","cat":"历史街区","stay":"40 分钟","score":4.8,"rev":11200,"addr":"邯郸市丛台区串城街南段","open":"全天开放","desc":"串城街南段的一条窄巷，相传是战国时赵国上卿蔺相如为避让大将军廉颇而回车让路之处，\"负荆请罪\"\"将相和\"的典故都出于此。巷口立有明代\"蔺相如回车巷\"石碑。巷子最窄处不足 3 米，两侧青砖墙高约 6 米——这个接近 1:2 的宽高比，是北方老城为冬季防风保温做出的选择。","view":["回车巷石碑","窄巷砖墙","将相和浮雕","串城街街口"],"audio":{"len":"02:12","txt":"语音讲解 · 回车这一步"},"tips":"巷内很窄，双向会人需侧身；石碑嵌在巷口东侧墙面内，容易错过。"}'::jsonb),
  ('pois','p3',2,'{"id":"p3","n":"秦始皇出生地纪念馆","r":"r1","ord":3,"ci":7,"lb":"奇货可居","cat":"文化场馆","stay":"40 分钟","score":4.6,"rev":5240,"addr":"邯郸市丛台区串城街 · 原朱家巷一带","open":"09:00-17:00","desc":"秦始皇嬴政的出生地。其父嬴异人早年在邯郸为质，后经吕不韦运作归秦，嬴政即生于赵都邯郸。纪念馆以\"奇货可居\"的历史脉络为主线，一层用沙盘呈现战国后期赵都邯郸的城市格局，二层展线讲述秦赵之间的往来与质子制度。","view":["朱家巷旧址","赵都格局沙盘","秦赵关系展","串城街院落"],"audio":{"len":"02:48","txt":"语音讲解 · 一个出生在邯郸的皇帝"},"tips":"与回车巷隔街相望，可一并参观；建议先看一层沙盘再上楼，展线更顺。"}'::jsonb),
  ('pois','p4',3,'{"id":"p4","n":"荀子文化园 · 荀子故居","r":"r1","ord":4,"ci":2,"lb":"赵国人荀子","cat":"文化场馆","stay":"35 分钟","score":4.5,"rev":3120,"addr":"邯郸市丛台区串城街中段","open":"09:00-17:00","desc":"荀子名况，赵国人，战国末期思想家。串城街内的这组仿古院落以\"劝学\"\"制天命而用之\"等主张作为展陈线索。院落是北方合院形制，正房采用抬梁式木构、进深较大以避冬季寒风，庭院尺度紧凑——与南方为通风遮阳而生的通透开敞，正好是两个方向的答案。","view":["仿古合院","抬梁式木构","劝学碑廊","院落天井"],"audio":{"len":"02:24","txt":"语音讲解 · 赵国人荀子"},"tips":"院落坐北朝南，正午光线最好；碑廊的刻石可以细看。"}'::jsonb),
  ('pois','p5',4,'{"id":"p5","n":"武灵丛台 · 赵武灵王点将台","r":"r1","ord":5,"ci":0,"lb":"胡服骑射","cat":"历史遗址","stay":"70 分钟","score":4.9,"rev":18600,"addr":"邯郸市丛台区中华北大街 · 丛台公园内","open":"06:00-21:00","desc":"相传为赵武灵王阅兵与观赏歌舞之处，\"胡服骑射\"的改革由此发端。丛台是战国\"高台建筑\"的代表性遗存——以夯土高台为基，台上再建据胜亭、回澜亭等。高台形制既是对地势的利用，也是权力在垂直方向上的表达。现存建筑为清代及近现代重修，丛台作为\"赵邯郸故城\"的组成部分，已列入全国重点文物保护单位。","view":["夯土高台","据胜亭","回澜亭","丛台碑刻"],"audio":{"len":"03:24","txt":"语音讲解 · 台为什么要这么高"},"tips":"登台需购票，台阶陡且窄，建议穿平底鞋；下午 4 点后台上光斜射，看细部最好。"}'::jsonb),
  ('pois','p6',5,'{"id":"p6","n":"一篓油水饺 · 老字号","r":"r2","ord":1,"ci":5,"lb":"老字号","cat":"地方餐饮","stay":"50 分钟","score":4.7,"rev":8420,"addr":"邯郸市丛台区 · 老城区","open":"10:00-20:30","desc":"邯郸老字号，店名取\"馅大汁足、咬开一篓油\"之意。皮薄馅实、现包现煮，是本地人从小吃到大的味道。老店的现状是无数北方老字号的共同样本：门脸不大、翻台极快、菜单只印一页，招牌菜三十年没变过。","view":["手工水饺","明档操作","老店门脸","本地食客"],"audio":{"len":"01:52","txt":"语音讲解 · 一篓油的来历"},"tips":"11:30 前到可避免排队；饺子按两卖，两人点两两半比较合适。"}'::jsonb),
  ('pois','p7',6,'{"id":"p7","n":"串城街夜市 · 老城夜食","r":"r2","ord":2,"ci":6,"lb":"烟火气","cat":"商业街区","stay":"80 分钟","score":4.8,"rev":16400,"addr":"邯郸市丛台区串城街","open":"全天开放","desc":"入夜后串城街两侧支起摊子，驴肉汤、邯郸焖子、武安拽面、磁县鲜粉皮、饸饹面与烤串在同一段街上排开。街道两侧是改造后的仿明清立面，青砖灰瓦之下是商铺的灯光——这种\"旧形制 + 新业态\"的组合，是当下历史文化街区更新最普遍的策略，也是串城街最值得讨论的地方。","view":["仿明清立面","夜食摊位","灯笼街灯","街巷纵深"],"audio":{"len":"02:30","txt":"语音讲解 · 一条街的两种时间"},"tips":"18:30-21:00 最热闹；夜市收摊约 22:30，想拍照建议 19:30 前后。"}'::jsonb),
  ('pois','p8',7,'{"id":"p8","n":"丛台广场 · 城市客厅","r":"r2","ord":3,"ci":8,"lb":"夜生活","cat":"城市广场","stay":"40 分钟","score":4.5,"rev":4860,"addr":"邯郸市丛台区中华北大街","open":"全天开放","desc":"串城街北端的城市广场，入夜后是本地人纳凉、跳舞、遛娃的场所。广场与丛台公园、串城街在空间上连成一个序列：园—街—场，三种公共空间的尺度在这里一次性展示出来——从围合的园林，到线性的商业街，再到开敞的广场。","view":["广场夜景","丛台灯光","市民活动","街巷对景"],"audio":{"len":"01:44","txt":"语音讲解 · 三种公共空间"},"tips":"夏夜 20:00 后有灯光效果；广场西侧可以同时望见丛台的轮廓。"}'::jsonb),
  ('pois','p9',8,'{"id":"p9","n":"邯郸市博物馆","r":"r3","ord":1,"ci":3,"lb":"国家一级博物馆","cat":"文化场馆","stay":"100 分钟","score":4.9,"rev":12800,"addr":"邯郸市丛台区中华北大街","open":"09:00-17:00（周一闭馆）","desc":"以磁山文化、赵文化、北朝造像与磁州窑四大体系为常设主线。武安磁山遗址出土的碳化粟标本，把黄河流域旱作农业的时间推到了约八千年前；赵文化展厅里的青铜器、瓦当与车马器，则是理解赵国都城形态最直接的材料。","view":["磁山文化展","赵文化青铜器","北朝造像","磁州窑瓷枕"],"audio":{"len":"03:36","txt":"语音讲解 · 八千年前的粮仓"},"tips":"周一闭馆；展线较长，建议预留 1.5 小时以上。"}'::jsonb),
  ('pois','p10',9,'{"id":"p10","n":"赵王城遗址公园","r":"r3","ord":2,"ci":1,"lb":"赵邯郸故城","cat":"历史遗址","stay":"80 分钟","score":4.7,"rev":6340,"addr":"邯郸市邯山区 · 赵王城遗址","open":"08:30-17:30","desc":"赵国宫城遗址，由东城、西城、北城组成\"品\"字形布局，城垣夯土台基至今仍在地表绵延数公里。站在龙台遗址上，可以看到城中高台与轴线如何组织起一座两千多年前的都城——这是中国城市史上最早的完整都城规划实例之一。","view":["龙台夯土台基","城墙遗迹","都城轴线","赵文化展陈馆"],"audio":{"len":"03:02","txt":"语音讲解 · 品字形的都城"},"tips":"以露天展示为主，夏季提前看天气并做好防晒；园区大，从西城入口进更顺。"}'::jsonb),
  ('pois','p11',10,'{"id":"p11","n":"赵苑公园 · 插箭岭与照眉池","r":"r3","ord":3,"ci":5,"lb":"苑囿遗址","cat":"园林遗址","stay":"60 分钟","score":4.5,"rev":3980,"addr":"邯郸市丛台区联纺东路","open":"06:00-21:00","desc":"依托战国赵国的苑囿遗址而建。\"插箭岭\"相传为赵武灵王练箭之处，\"照眉池\"相传为宫中女子梳妆之地。地表仍可辨认夯土高台与水域的关系——苑囿在赵国的形态，在这里留下了可以用脚走一遍的地形轮廓。","view":["插箭岭夯土","照眉池水面","苑囿地形","赵苑绿荫"],"audio":{"len":"02:18","txt":"语音讲解 · 王的猎场"},"tips":"免费开放；插箭岭一带地形起伏，雨后路面湿滑。"}'::jsonb),
  ('pois','p12',11,'{"id":"p12","n":"广府古城 · 水城与城墙","r":"r4","ord":1,"ci":2,"lb":"北方水城","cat":"古城","stay":"100 分钟","score":4.8,"rev":10400,"addr":"邯郸市永年区广府镇","open":"08:00-18:00","desc":"永年广府古城现存城墙为明代砖砌，周长约 4.5 公里、高约 12 米，城外护城河与永年洼湿地环绕，形成\"一城双水\"的格局——这在北方干旱地区极为罕见。城墙顶部可环行，是观察明代北方城池防御体系与砖砌做法的一手样本。","view":["明代砖城墙","护城河水面","永年洼湿地","城门与瓮城"],"audio":{"len":"03:18","txt":"语音讲解 · 北方为什么会有水城"},"tips":"城墙可租自行车环行；夏季洼地蚊虫多，备好驱蚊用品。"}'::jsonb),
  ('pois','p13',12,'{"id":"p13","n":"弘济桥 · 隋代石拱桥","r":"r4","ord":2,"ci":3,"lb":"赵州桥姊妹桥","cat":"历史建筑","stay":"40 分钟","score":4.8,"rev":5960,"addr":"邯郸市永年区广府镇东桥村","open":"全天开放","desc":"横跨滏阳河故道的敞肩式石拱桥，结构与赵州桥同源：主拱两端各开小拱，既减轻自重又能泄洪。桥面栏板与望柱上留有浮雕，石料以青石为主。作为隋代桥梁做法的实物，它的价值在于为赵州桥提供了一条可以互证的证据链。","view":["敞肩主拱","小拱泄洪","栏板浮雕","滏阳河道"],"audio":{"len":"02:26","txt":"语音讲解 · 和赵州桥是一家的"},"tips":"桥上仍有通行，注意来车；要看拱券构造需下到河滩侧。"}'::jsonb),
  ('pois','p14',13,'{"id":"p14","n":"杨露禅故居 · 太极发源地","r":"r4","ord":3,"ci":7,"lb":"杨式太极","cat":"名人故居","stay":"40 分钟","score":4.6,"rev":4120,"addr":"邯郸市永年区广府镇南关","open":"08:30-17:30","desc":"杨式太极拳创始人杨露禅的故居，位于广府古城南关，是一组北方四合院式民居。正房、厢房与院落尺度紧凑，反映的是晚清北方县城中等人家的居住形态。永年是杨式、武式两大太极拳流派共同的发源地。","view":["四合院落","正房木构","演武场","故居展陈"],"audio":{"len":"02:14","txt":"语音讲解 · 一个县城出的两门太极"},"tips":"晨间常有本地人在此练拳，可以看但不必打扰；拍摄前先询问。"}'::jsonb),
  ('pois','p15',14,'{"id":"p15","n":"响堂山石窟","r":"r5","ord":1,"ci":1,"lb":"北齐造像","cat":"石窟寺","stay":"120 分钟","score":4.9,"rev":7820,"addr":"邯郸市峰峰矿区 / 武安市 · 太行山东麓","open":"08:00-17:00","desc":"分南响堂与北响堂两处，开凿于北齐，是北朝晚期佛教造像与石窟形制的重要遗存。塔形窟与中心方柱窟的组合，呈现了北齐石窟从外来形制走向本土做法的关键一步；造像的\"北齐样式\"——体态丰满、衣纹贴体——在美术史上影响深远。","view":["塔形窟","中心方柱窟","北齐造像","刻经洞"],"audio":{"len":"04:12","txt":"语音讲解 · 北齐的一张脸"},"tips":"南、北两区相距较远，需分两次参观；窟内禁止闪光灯，部分造像已流失海外。"}'::jsonb),
  ('pois','p16',15,'{"id":"p16","n":"磁州窑遗址 · 彭城窑火","r":"r5","ord":2,"ci":4,"lb":"白地黑花","cat":"历史遗址","stay":"90 分钟","score":4.8,"rev":6480,"addr":"邯郸市峰峰矿区彭城镇","open":"08:30-17:30","desc":"磁州窑是宋代北方民窑的代表，以\"白地黑花\"的化妆土绘花与剔划工艺闻名，把文人的书画趣味带进了日用器物。彭城一带现存窑址、作坊与窑神庙遗存，可以看到从拉坯、施化妆土到剔刻、入窑的完整工艺链条。","view":["馒头窑遗迹","白地黑花瓷片","剔刻工艺","窑神庙"],"audio":{"len":"03:08","txt":"语音讲解 · 土与火的分工"},"tips":"可顺路参观磁州窑博物馆；体验工坊需提前预约。"}'::jsonb),
  ('pois','p17',16,'{"id":"p17","n":"娲皇宫 · 悬空而建","r":"r5","ord":3,"ci":0,"lb":"女娲祭典","cat":"宗教建筑","stay":"100 分钟","score":4.8,"rev":9160,"addr":"邯郸市涉县索堡镇 · 中皇山","open":"07:30-18:00","desc":"依山崖崖壁而建的一组建筑群，以\"悬空\"著称：建筑背倚崖壁，前以木柱支撑，在陡峭山体上争取出完整的楼阁空间。女娲祭典已列入国家级非物质文化遗产名录。从建筑角度看，它解决的是同一个问题——在地形几乎不给余地的地方，如何用最少的地面换取最多的使用空间。","view":["悬空楼阁","摩崖刻经","补天石","山崖栈道"],"audio":{"len":"03:30","txt":"语音讲解 · 挂在崖壁上"},"tips":"上行多为石阶，体力一般可从索道上山；摩崖刻经需单独购票，别错过。"}'::jsonb),
  ('notes','n1',0,'{"id":"n1","au":"阿森","av":"a","t":"在串城街迷路的一下午","h":210,"ci":4,"body":"本来只想拍街口的石碑，结果拐进一条没有名字的巷子，被一位大爷拉去看他家的老门楼。他说这条街以前更窄，两边都是自家院墙，冬天站在巷里不冷，风从街口一过就走了。\n\n突然明白北方的巷子为什么修得这么窄——它不是为了好看，是为了挡风。","topic":"#赵都建筑","poi":"p2","route":"r1","fav":1268,"like":3400,"cmt":88,"tags":["建筑","街巷"]}'::jsonb),
  ('notes','n2',1,'{"id":"n2","au":"小满","av":"b","t":"丛台的瓦当，我抬头看了半小时","h":170,"ci":0,"body":"所有人都挤在台上拍照，只有我在台下抬头。\n\n檐口的瓦当一层压一层，从下往上收得很有道理。凑近看，连滴水上的纹样都不是重复的。一个两千年后重修的建筑，居然还愿意在这种地方花心思。","topic":"#赵都建筑","poi":"p5","route":"r1","fav":942,"like":2180,"cmt":52,"tags":["工艺","细节"]}'::jsonb),
  ('notes','n3',2,'{"id":"n3","au":"Kiwi","av":"c","t":"串城街拍照机位，8 个位置实测","h":240,"ci":6,"body":"走了三小时整理出来的机位：\n①街口牌坊下，压低机位仰拍；②夜市灯笼段，等一位骑车人经过；③青砖墙面旁，侧光下午 4 点半最好……\n\n最重要的一条：不要站在街中间，这条街上真的有人在生活。","topic":"#拍照机位","poi":"p7","route":"r2","fav":2310,"like":5620,"cmt":174,"tags":["摄影","攻略"]}'::jsonb),
  ('notes','n4',3,'{"id":"n4","au":"老陈","av":"d","t":"回车巷不到 3 米宽，我拿尺子量了一下","h":190,"ci":4,"body":"实测最窄处 2.8 米，两侧墙高约 6 米，宽高比接近 1:2。\n\n这个比例在南方会被嫌弃——太暗。但在北方它是合理的：冬季太阳高度角低，正午前后直射光仍能照到巷底，而窄巷本身把冬季西北风挡在外面。采光和保温在北方老城里是一笔要一起算的账。","topic":"#赵都建筑","poi":"p2","route":"r1","fav":1580,"like":3930,"cmt":96,"tags":["建筑","采光"]}'::jsonb),
  ('notes','n5',4,'{"id":"n5","au":"阿森","av":"a","t":"邯郸早餐生存指南（外地人版）","h":230,"ci":5,"body":"① 7 点前到，晚了老店就只剩素馅；\n② 驴肉汤配饼，汤可以免费续，别不好意思；\n③ 饺子按两卖，第一次点两两就够；\n④ 结账前记得看一眼墙上贴的单子，有时候手写的是老价格。\n\n最重要：慢一点。这顿饭本来就是用来开始的。","topic":"#邯郸美食","poi":"p6","route":"r2","fav":3120,"like":7840,"cmt":268,"tags":["美食","攻略"]}'::jsonb),
  ('notes','n6',5,'{"id":"n6","au":"Kiwi","av":"c","t":"博物馆里最打动我的，是八千年前的一粒粟","h":180,"ci":3,"body":"一粒碳化的粟米，比米粒还小，装在展柜正中间。\n\n它出土在武安磁山，说明八千年前这片土地上的人已经在种地了。一座以\"成语\"闻名的城市，最早的故事其实写在土里。","topic":"#博物馆","poi":"p9","route":"r3","fav":760,"like":1840,"cmt":41,"tags":["历史","考古"]}'::jsonb),
  ('notes','n7',6,'{"id":"n7","au":"小满","av":"b","t":"在丛台广场坐到路灯亮起","h":250,"ci":8,"body":"下午来的时候广场上只有几个下棋的老人，等我再抬头，跳舞的、遛娃的、卖气球的全都出来了，路灯一起亮。\n\n同一个场地，两个小时里换了三拨人。城市的好，有时候就是这么具体的事。","topic":"#城市夜景","poi":"p8","route":"r2","fav":1120,"like":2760,"cmt":63,"tags":["夜景","生活"]}'::jsonb),
