  ('products','g5',4,'{"id":"g5","t":"大名府烧鸡香肠礼盒","price":128,"old":168,"lb":"地方特产","ci":3,"cat":"goods","sell":"已售 2180","rate":4.8,"spec":["烧鸡 1 只","烧鸡 1 只 + 香肠 2 袋","双人礼盒装"],"shop":"邯道优选","story":"大名二毛烧鸡与五百居香肠都是邯郸本地的老字号，制作技艺延续百年。礼盒采用真空封装，常温可存放，是当地人最常带出门的手信组合。"}'::jsonb),
  ('products','g6',5,'{"id":"g6","t":"邯郸剪纸冰箱贴 · 六款","price":39,"old":0,"lb":"文创","ci":1,"cat":"goods","sell":"已售 4210","rate":4.9,"spec":["随机一款","全套 6 款","全套 + 磁贴板"],"shop":"邯道文创","story":"邯郸剪纸以线条细密、构图饱满见长，题材多为丛台、回车巷、太极与民俗场景。六款图案分别取自邯郸老城与广府古城的经典景观。"}'::jsonb),
